 start=time.monotonic();result={'task_id':'IA-NARRATIVE-TECH-PASS02-001','aggregate_pass':2,'aggregate_limit':5,'counterchecks_completed_before_run':1,'countercheck_requested':2,'environment':'PostgreSQL17 isolated narrative_tech_pass02; synthetic minimal dependencies','provider_calls':0,'production_writes':0,'max_groups':8,'groups':[],'limits':['Auth/API/hosted Deno not tested','existing snapshot persistence lifecycle and concurrency not recertified','minimal tables, native function bodies pinned; unrelated bodies unexecuted','catalog content not corrected; new movement modes not runtime certified']}
