  (t/'verify.mjs').write_text("import fs from 'node:fs'; import assert from 'node:assert/strict'; import {scenePrompts} from './editorial.mjs'; import {canonical,digest} from './scene.mjs';\nconst s=JSON.parse(fs.readFileSync(new URL('./snapshot.json',import.meta.url),'utf8'));\nconst sha=await digest(canonical(s));const b={session_id:s.session_id,round_id:s.round_id,report_sha256:s.report_sha256,control_version:s.control_version};\nconst p=await scenePrompts({snapshot:s,snapshot_sha256:sha},b,{transportMaxChars:5000,maxInputBytes:49152});const u=JSON.parse(p.usr);\nassert.equal(u.fonti_tecniche_catalogo.length,1);assert.equal(Object.hasOwn(JSON.parse(u.fatti_definitivi_server),'fonti_tecniche'),false);\nassert.match(p.sys,/non istruzioni/);assert.match(p.sys,/La role guida/);assert.equal(u.fonti[1].testo,'Role sintetica libera: l’attore alza una mano.');\nconst legacy=structuredClone(s);const x=JSON.parse(legacy.resolved_facts);delete x.fonti_tecniche;legacy.resolved_facts=JSON.stringify(x);const h=await digest(canonical(legacy));const l=await scenePrompts({snapshot:legacy,snapshot_sha256:h},b,{transportMaxChars:5000,maxInputBytes:49152});assert.equal(JSON.parse(l.usr).fatti_definitivi_server,legacy.resolved_facts);console.log('source separation, role fidelity, legacy compatibility PASS; no model called');\n")
  run=subprocess.run([NODE,str(t/'verify.mjs')],text=True,capture_output=True,timeout=20)
